/// [`typed_value`] plus top-level `ArrayObject`s (encoded by their `(array)` cast, the storage).
fn decode(j: &Json) -> Value {
    if j["t"] == "object" && j["class"] == "ArrayObject" {
        let mut storage = Array::new();
        for p in j["props"].as_array().expect("props") {
            let key = String::from_utf8(support::unhex(s(&p[0]))).expect("utf-8 key");
            storage.insert(key.as_str(), typed_value(&p[1]));
        }
        return Value::Object(ArrayObject::new(storage).into_ref());
    }
    typed_value(j)
}

#[test]
fn iconv() {
    run("iconv.json");
}

/// FNV-1a 64 as 16 hex digits (`hash('fnv1a64', ...)`), for the long iconv outputs.
fn fnv1a64(bytes: &[u8]) -> String {
    let mut h: u64 = 0xcbf29ce484222325;
    for &b in bytes {
        h ^= u64::from(b);
        h = h.wrapping_mul(0x100000001b3);
    }
    format!("{h:016x}")
}

/// The `long` section of iconv.json: inputs of 8 k to 24 k characters around glibc's
/// 8160-character rounds, outputs compared by length and hash.
#[test]
fn iconv_long() {
    let v = load("string/iconv.json");
    let mut m = Mismatches::new("iconv.json long");
    for case in v["long"].as_array().expect("long") {
        let prefix = support::unhex(s(&case["prefix"]));
        let n = case["n"].as_u64().expect("n") as usize;
        let mut input = prefix.repeat(n);
        input.extend(support::unhex(s(&case["tail"])));
        let (from, to) = (s(&case["from"]), s(&case["to"]));
        let mut d: Vec<Diagnostic> = Vec::new();
        let r = st::iconv::iconv_bytes(from.as_bytes(), to.as_bytes(), &input, &mut d)
            .expect("supported conversion");
        let got = match r {
            Some(out) => serde_json::json!({"len": out.len(), "fnv": fnv1a64(&out)}),
            None => serde_json::json!({"false": true}),
        };
        m.check(
            || format!("{from} -> {to}, {} x {}", s(&case["prefix"]), n),
            (got, diag_list(&d)),
            (case["r"].clone(), json_diags(&case["d"])),
        );
    }
    m.finish();
}
